      "content": "MAPO TOFU\nMAPO TOFU ALAP KÖZPONTI KONYHA\nMAPO ALAP\n2.4x\nalapanyag\n2880\ng\nrepce olaj\n30\nkg\npucolt kockázott vörös\nhagyma\n600\ng\nGyömbér finomra vágva\n850\ng\ntisztított Fokhagyma\nfinomra vágva\n5050\ng\nTobanjan\n28\nkg\nSzűrt víz\n180\ng\nKínai gomba por\n4010\ng\nVilágos szójaszósz\n870\ng\nCukor\n2050\ng\nShaoxin főzőbor\n240\ng\nbolti szecsuáni olaj\n2.8\nl\nvíz\n1400\ng\nKukoricakeményítő\nMegjegyzés:\nKínai gomba por:Liroy.nl / PanAsia / Asia Gasztro / BidFood / Duna Panda bolti szecsuáni olaj:Duna Panda\nMűveletek:\n/ A kockázott hagymát és az olajat öntsd a bukoustbe és alaposan keverd össze.\n/ Parold uvegesre.\n/ Add az olajos hagymához a fokhagymát, a gyömbért és a tobanjant és alacsony fokozaton folyamatos kevergetés közben párold még 10-12 percig.\n/ Öntsd fel a szűrt vízzel, a szójaszósszal, gombaporral, és add hozzá a cukrot, a főzőbort illetve a bolti szecsuáni olajat. Kapcsold nagy fokozatra és forrald fel.\n/ A keményítőt alaposan keverd el a maradék vízzel (az anyaghányados lista alsó részén), úgy hogy csomómentes legyen. folyamatosan keverve vékony sugárban öntsd a forrásban lévő mapo alaphoz. Forrald fel újra a mapot és alacsony lángon forrald 2-3 percig amíg szép fényes és sűrű nem lesz a keményítőtől.\nHabverővel sűrítés\n/ Öntsd át egy mély gasztronormba és rakd a sokkolóba. Rakd bele a maghőmérőt és sokkold le 3C-ra. Amint lehűlt vákuumozd le 2.5kg-ként, és sokkolva fagyaszd le. Sokkolva fagyasztva 3 hónapig tárolható, olvasztás után 5 nap az eltarthatósági ideje.",
      "hungarianNotes": "MAPO TOFU\nMAPO TOFU ALAP KÖZPONTI KONYHA\nMAPO ALAP\n2.4x\nalapanyag\n2880\ng\nrepce olaj\n30\nkg\npucolt kockázott vörös\nhagyma\n600\ng\nGyömbér finomra vágva\n850\ng\ntisztított Fokhagyma\nfinomra vágva\n5050\ng\nTobanjan\n28\nkg\nSzűrt víz\n180\ng\nKínai gomba por\n4010\ng\nVilágos szójaszósz\n870\ng\nCukor\n2050\ng\nShaoxin főzőbor\n240\ng\nbolti szecsuáni olaj\n2.8\nl\nvíz\n1400\ng\nKukoricakeményítő\nMegjegyzés:\nKínai gomba por:Liroy.nl / PanAsia / Asia Gasztro / BidFood / Duna Panda bolti szecsuáni olaj:Duna Panda\nMűveletek:\n/ A kockázott hagymát és az olajat öntsd a bukoustbe és alaposan keverd össze.\n/ Parold uvegesre.\n/ Add az olajos hagymához a fokhagymát, a gyömbért és a tobanjant és alacsony fokozaton folyamatos kevergetés közben párold még 10-12 percig.\n/ Öntsd fel a szűrt vízzel, a szójaszósszal, gombaporral, és add hozzá a cukrot, a főzőbort illetve a bolti szecsuáni olajat. Kapcsold nagy fokozatra és forrald fel.\n/ A keményítőt alaposan keverd el a maradék vízzel (az anyaghányados lista alsó részén), úgy hogy csomómentes legyen. folyamatosan keverve vékony sugárban öntsd a forrásban lévő mapo alaphoz. Forrald fel újra a mapot és alacsony lángon forrald 2-3 percig amíg szép fényes és sűrű nem lesz a keményítőtől.\nHabverővel sűrítés\n/ Öntsd át egy mély gasztronormba és rakd a sokkolóba. Rakd bele a maghőmérőt és sokkold le 3C-ra. Amint lehűlt vákuumozd le 2.5kg-ként, és sokkolva fagyaszd le. Sokkolva fagyasztva 3 hónapig tárolható, olvasztás után 5 nap az eltarthatósági ideje.",
      "englishNotes": "Mapo Tofu is an imported English working title. Review the translated ingredients and method before kitchen use.",
