      "content": "Bao\nBAO TÉSZTA\nsuly\nalapanyag\n2.5\nkg\nRétesliszt\n333\ng\nTejpor\n20\ng\nSó\n20\ng\nKínai sütőpor\n25\ng\nglutén v. búzasikér\n240\ng\nCukor\n25\ng\nFriss élesztő - budafoki\n420\ng\nViz\n130\ng\nOlaj- repce\n1000\ng\nTangzhong\nMegjegyzés:\nKínai sütőpor: liroy.nl v. duna panda v. asia gastro búzasikér : Békás\nFriss élesztő - budafoki : Békás 5x 500 g rendelés Műveletek:\nMeleg vízben(max 40 fok) oldd fel a cukrot, majd morzsold bele az élesztőt, és keverd el alaposan. 15 percet áll.\nAmeddig áll addig mérd ki a szárazárut(liszt, só, kínai sütópor, buzasiker) és tedd bele a dagasztóba. Ezt be kell kapcsolni. Gyors fokozaton.\nAmeddig kavarog, addig mérd rá az olajat a cukros élesztős vízre.\nMérd ki a tangzhong külön edénybe.\nA gépbe add hozzá a folyadékokat. Előszor a cukros élesztős vizet, majd a tangzhong -ot.\nHagyd menni a gépet 15 percig. Tésztagyúrás.\nKiveszed a tésztát és átgyúrod.Ezt követően szétszeded 2250 g- os labdákra.\nA labdákat a beolajozott lapon pizza alakőra nyújtod a formázó lapon.\nZsemle kerekítő gépbe beteszed. Rutinszerűen vágod.\n74,5 g - 75,5 g golyókat csinálsz. Mérleggel méred ki.\nKézzel bao kerekítés. Mantao: kész\nShiao song : hosszú hengerekete gyúrsz\nGua : Kézzel kilapított kerek alakúra, majd nyújtógéppel kinyújtod. Olajozod és félbe hajtod.\n70 percig keleszted. !! Amennyiben nem kel meg, akkor még hagyod állni.\nKÍnai gőzölőben 100 fok 6 perc, 110 fokon 6 perc\nKihűtöd és csomagolod.\nNagy zacsiba Gua: 16 - Shia song: 18 - Mantao: 20",
      "hungarianNotes": "Bao\nBAO TÉSZTA\nsuly\nalapanyag\n2.5\nkg\nRétesliszt\n333\ng\nTejpor\n20\ng\nSó\n20\ng\nKínai sütőpor\n25\ng\nglutén v. búzasikér\n240\ng\nCukor\n25\ng\nFriss élesztő - budafoki\n420\ng\nViz\n130\ng\nOlaj- repce\n1000\ng\nTangzhong\nMegjegyzés:\nKínai sütőpor: liroy.nl v. duna panda v. asia gastro búzasikér : Békás\nFriss élesztő - budafoki : Békás 5x 500 g rendelés Műveletek:\nMeleg vízben(max 40 fok) oldd fel a cukrot, majd morzsold bele az élesztőt, és keverd el alaposan. 15 percet áll.\nAmeddig áll addig mérd ki a szárazárut(liszt, só, kínai sütópor, buzasiker) és tedd bele a dagasztóba. Ezt be kell kapcsolni. Gyors fokozaton.\nAmeddig kavarog, addig mérd rá az olajat a cukros élesztős vízre.\nMérd ki a tangzhong külön edénybe.\nA gépbe add hozzá a folyadékokat. Előszor a cukros élesztős vizet, majd a tangzhong -ot.\nHagyd menni a gépet 15 percig. Tésztagyúrás.\nKiveszed a tésztát és átgyúrod.Ezt követően szétszeded 2250 g- os labdákra.\nA labdákat a beolajozott lapon pizza alakőra nyújtod a formázó lapon.\nZsemle kerekítő gépbe beteszed. Rutinszerűen vágod.\n74,5 g - 75,5 g golyókat csinálsz. Mérleggel méred ki.\nKézzel bao kerekítés. Mantao: kész\nShiao song : hosszú hengerekete gyúrsz\nGua : Kézzel kilapított kerek alakúra, majd nyújtógéppel kinyújtod. Olajozod és félbe hajtod.\n70 percig keleszted. !! Amennyiben nem kel meg, akkor még hagyod állni.\nKÍnai gőzölőben 100 fok 6 perc, 110 fokon 6 perc\nKihűtöd és csomagolod.\nNagy zacsiba Gua: 16 - Shia song: 18 - Mantao: 20",
