      "content": "Kimcsi_kk\nARANY KIMCSI\nSULY\nALAPANYAGOK\n90\nkg\nKinai kel\n45\nKg\nkaposzta / ne lila és ne kel\n45\nkg\nJegcsapretek\n45\nkg\nalma - héjastul\n40\nkg\nRepa\n45\nkg\nkaralabe\nKimcsi szósz\n1500\ng\nfokhagyma - tisztított\n1500\ng\nGyomber - tisztított\n3800\ng\nFermentalt tofu\n10400\ng\nRepa darabokra vagva\n7500\ng\nViz\n1350\ng\nCukor\n13500\ng\nRizsecet\n1200\ng\nSarga chilli\n2100\ng\nSzezam olaj\neredeti\n900\ng\nTengeri so ???\n300\ng\nDinatrium 5 ribonukleotid\n90\ng\nxantan\nMegjegyzés:\nXantan a végén adom hozzá folyamatos kevergetés mellett.\nAz egesz folyamatot kezdd azzal hogy a hordokat es a tetoket makulatlanul fertotlenitsd el.\nEhhez szappanos vizzel mosd at, torold szarazra majd alkohollal hogy csiramentes legyen.\nA kinai kelt a kaposztat tisztitsd meg es vagd 2x2 cm-es kockara.\nA jegcsapretket, karalábé megpucolod géppel szeleteled 1,5 mm fejjel.\nrépát megpucolod és kis lyukú szeletelőn áttolod.\nAlma: Negyedeled és kicsumázod. Citromsavas/ citrmolé vízben tárolod, hogy ne barnuljon meg. Ezt követően 3 mm es fejjel szeleteled.\nAlapléfőzőbe teszek 12 kg sót a zöldségre és feltöltöm a jelig. Hagyom állni másnapig.\nA zöld hordóba 6 kg só megy. 5%-os sóoldatot használunk. Az összes zöldség 1 éjszakát áll.\nMásnap: Ki kell facsarni a zöldséget és beletöltöm a hordóba kimcsi szósszal keverve. Ezt megtehetem szőlőpréssel, kézzel, súlyozva a fém szitán.\nAkár alapléfőzőbe a tetejére nagy kondért teszek, amit tele rakok súllyal. Csap alul megnyit.\nA hordókban le kell súlyozni vízzel. Nagy zacsi vákumozva.\n1 hétig hagyom állni szobahőn. 1 hét múlva átmozgatom. Majd még egy hét múlva átmozgatom. Ezt követően behúzom a hűtőbe.\nNyáron hamarabb be kell rakni a hűtőbe.",
      "hungarianNotes": "Kimcsi_kk\nARANY KIMCSI\nSULY\nALAPANYAGOK\n90\nkg\nKinai kel\n45\nKg\nkaposzta / ne lila és ne kel\n45\nkg\nJegcsapretek\n45\nkg\nalma - héjastul\n40\nkg\nRepa\n45\nkg\nkaralabe\nKimcsi szósz\n1500\ng\nfokhagyma - tisztított\n1500\ng\nGyomber - tisztított\n3800\ng\nFermentalt tofu\n10400\ng\nRepa darabokra vagva\n7500\ng\nViz\n1350\ng\nCukor\n13500\ng\nRizsecet\n1200\ng\nSarga chilli\n2100\ng\nSzezam olaj\neredeti\n900\ng\nTengeri so ???\n300\ng\nDinatrium 5 ribonukleotid\n90\ng\nxantan\nMegjegyzés:\nXantan a végén adom hozzá folyamatos kevergetés mellett.\nAz egesz folyamatot kezdd azzal hogy a hordokat es a tetoket makulatlanul fertotlenitsd el.\nEhhez szappanos vizzel mosd at, torold szarazra majd alkohollal hogy csiramentes legyen.\nA kinai kelt a kaposztat tisztitsd meg es vagd 2x2 cm-es kockara.\nA jegcsapretket, karalábé megpucolod géppel szeleteled 1,5 mm fejjel.\nrépát megpucolod és kis lyukú szeletelőn áttolod.\nAlma: Negyedeled és kicsumázod. Citromsavas/ citrmolé vízben tárolod, hogy ne barnuljon meg. Ezt követően 3 mm es fejjel szeleteled.\nAlapléfőzőbe teszek 12 kg sót a zöldségre és feltöltöm a jelig. Hagyom állni másnapig.\nA zöld hordóba 6 kg só megy. 5%-os sóoldatot használunk. Az összes zöldség 1 éjszakát áll.\nMásnap: Ki kell facsarni a zöldséget és beletöltöm a hordóba kimcsi szósszal keverve. Ezt megtehetem szőlőpréssel, kézzel, súlyozva a fém szitán.\nAkár alapléfőzőbe a tetejére nagy kondért teszek, amit tele rakok súllyal. Csap alul megnyit.\nA hordókban le kell súlyozni vízzel. Nagy zacsi vákumozva.\n1 hétig hagyom állni szobahőn. 1 hét múlva átmozgatom. Majd még egy hét múlva átmozgatom. Ezt követően behúzom a hűtőbe.\nNyáron hamarabb be kell rakni a hűtőbe.",
