        "Egy edényben a ragacsos Ricelisztet keverd össze a waterzel. Nagy hőmérséklettel kezdve, és folyamatosan csökkentve a hőmérsékletet főzd amíg az egész nem áll össze egy ragacsos tésztává. Ekkor kapcsold le.",
