        "Bélelj ki sütőpapírral egy gn talcat. A mixet ontsd a tepsibe es fedd le megegy reteg sutopapirral. Gőzöld ki 100C fokon 1óráig majd a sokkolóban coolsd le 3c fokra.",
        "Porciózd 70g-os négyzet alakú szeletekre."
