      "content": "DAIKON CAKE\n1 TALCA\nalapanyag\n1800\ng\nkaralábé v. jégcsapretek\n800\ng\nKukoricakeményítő\n40\ng\nSzezám olaj\n400\ng\nRopogós hagyma\n16\ng\nsó\n20\ng\ncukor\n2\ng\nőrölt feherbors\n30\ng\nGomba por\n400\ng\nRagacsos rizsliszt\n1500\ng\nVíz\nMEgjegyzés:\nÉrdemes több tálcába tenni és 1 ujjnyi vastag legyen. Műveletek:\nAz 1800 g az a tisztított, sózott mennyiség. Megjön a jégcsapretek, amit megpucolok.Lereszelem a géppel. besózom, Hagyom állni 30 percet majd kinyomkodom. Le kell súlyozni, hogy kicsepegjen.\nEzt követően lemérem és ehhez igazítom a receptet.\nKimérem a száraz cuccokat egy külön edényben.Kukoricakeményítő,Ropogós hagyma,só, cukor,őrölt feherbors, Gomba por\nEgy edényben a ragacsos rizslisztet keverd össze a vízzel. Nagy hőmérséklettel kezdve, és folyamatosan csökkentve a hőmérsékletet főzd amíg az egész nem áll össze egy ragacsos tésztává. Ekkor kapcsold le.\nA kicsavart reteket illetve a már összefőzött ragacsos rizsliszt tésztát keverd össze az összes többi alapanyaggal.\nBélelj ki sütőpapírral egy gn talcat. A mixet ontsd a tepsibe es fedd le megegy reteg sutopapirral. Gőzöld ki 100C fokon 1óráig majd a sokkolóban hűtsd le 3c fokra.\nPorciózd 70g-os négyzet alakú szeletekre.\nTészta",
      "hungarianNotes": "DAIKON CAKE\n1 TALCA\nalapanyag\n1800\ng\nkaralábé v. jégcsapretek\n800\ng\nKukoricakeményítő\n40\ng\nSzezám olaj\n400\ng\nRopogós hagyma\n16\ng\nsó\n20\ng\ncukor\n2\ng\nőrölt feherbors\n30\ng\nGomba por\n400\ng\nRagacsos rizsliszt\n1500\ng\nVíz\nMEgjegyzés:\nÉrdemes több tálcába tenni és 1 ujjnyi vastag legyen. Műveletek:\nAz 1800 g az a tisztított, sózott mennyiség. Megjön a jégcsapretek, amit megpucolok.Lereszelem a géppel. besózom, Hagyom állni 30 percet majd kinyomkodom. Le kell súlyozni, hogy kicsepegjen.\nEzt követően lemérem és ehhez igazítom a receptet.\nKimérem a száraz cuccokat egy külön edényben.Kukoricakeményítő,Ropogós hagyma,só, cukor,őrölt feherbors, Gomba por\nEgy edényben a ragacsos rizslisztet keverd össze a vízzel. Nagy hőmérséklettel kezdve, és folyamatosan csökkentve a hőmérsékletet főzd amíg az egész nem áll össze egy ragacsos tésztává. Ekkor kapcsold le.\nA kicsavart reteket illetve a már összefőzött ragacsos rizsliszt tésztát keverd össze az összes többi alapanyaggal.\nBélelj ki sütőpapírral egy gn talcat. A mixet ontsd a tepsibe es fedd le megegy reteg sutopapirral. Gőzöld ki 100C fokon 1óráig majd a sokkolóban hűtsd le 3c fokra.\nPorciózd 70g-os négyzet alakú szeletekre.\nTészta",
