      "content": "SZECSUÁNI CHILLI OLAJ\nSZECSUÁNI CHILLI OLAJ & MORZSA\nSZECSUÁNI OLAJ\nAmount\nIngredients\n18000\ng\nRepce olaj\n1080\ng\nFokhagyma\n1200\ng\nGyömbér\n180\ng\nCsillagánizs\n110\ng\nKoriander mag\n900\ng\nSzecsuáni vörös bors\n3600\ng\nKoreai chilli pehely (gochugaru)\n250\ng\nSó\n500\ng\nSzezám Olaj\nMegjegyzés:\nSan Bei szószból megmaradt olajjal csináljuk. Nem kell ezért fokhagyma, gyömbér.\nMűveletek:\n1. A szecsuáni borsot, a koriandert es a csillagánizst mérd ki és 170C fokos sütőben 2-es légkeringetés mellett szárazon pirítsd meg lapos tálcákon úgy 8 percig.\nA fűszereket 500 g onként tedd egy tálcára.\nKeverj össze minden szaraz fuszert beleértve a gochugarut is. őröld porrá az összeset és rakd egy 50 literes fazékba.\nMelegítsd fel az olajat 150 fokra és ráöntöd a száraz füszerekre.\nAlaposan keverd el az olajat a fűszerekkel és hagyd állni 1 napot majd szűrd le az olajat párnahuzattal. A chilli morzsát vedd külön és vákuumozd le. 1 kg onként.\nAz olaj innen már használhato 3 hónap az eltarthatósági ideje.",
      "hungarianNotes": "SZECSUÁNI CHILLI OLAJ\nSZECSUÁNI CHILLI OLAJ & MORZSA\nSZECSUÁNI OLAJ\nAmount\nIngredients\n18000\ng\nRepce olaj\n1080\ng\nFokhagyma\n1200\ng\nGyömbér\n180\ng\nCsillagánizs\n110\ng\nKoriander mag\n900\ng\nSzecsuáni vörös bors\n3600\ng\nKoreai chilli pehely (gochugaru)\n250\ng\nSó\n500\ng\nSzezám Olaj\nMegjegyzés:\nSan Bei szószból megmaradt olajjal csináljuk. Nem kell ezért fokhagyma, gyömbér.\nMűveletek:\n1. A szecsuáni borsot, a koriandert es a csillagánizst mérd ki és 170C fokos sütőben 2-es légkeringetés mellett szárazon pirítsd meg lapos tálcákon úgy 8 percig.\nA fűszereket 500 g onként tedd egy tálcára.\nKeverj össze minden szaraz fuszert beleértve a gochugarut is. őröld porrá az összeset és rakd egy 50 literes fazékba.\nMelegítsd fel az olajat 150 fokra és ráöntöd a száraz füszerekre.\nAlaposan keverd el az olajat a fűszerekkel és hagyd állni 1 napot majd szűrd le az olajat párnahuzattal. A chilli morzsát vedd külön és vákuumozd le. 1 kg onként.\nAz olaj innen már használhato 3 hónap az eltarthatósági ideje.",
